<script setup lang="ts">import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import DataTable from '@/components/zs/DataTable.vue';import StatusBadge from '@/components/zs/StatusBadge.vue';import ZButton from '@/components/zs/ZButton.vue';import {useCrmData} from '@/composables/useCrmData';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Outreach Automations','Manage sequence enrollment and status.');const d=useCrmData(),r=useRouter(),local=ref<Record<string,string>>({});const rows=computed(()=>(d.sequences.data.value??[]).map(x=>({...x,status:local.value[x.id]??x.status})));const columns=[{key:'name',header:'Sequence'},{key:'enrolled',header:'Leads enrolled',align:'right' as const},{key:'active',header:'Active',align:'right' as const},{key:'completed',header:'Completed',align:'right' as const},{key:'replied',header:'Replied',align:'right' as const},{key:'openRate',header:'Open rate',align:'right' as const},{key:'replyRate',header:'Reply rate',align:'right' as const},{key:'status',header:'Status'},{key:'actions',header:'',align:'right' as const}];</script>
<template><AppShell><PageHeader title="Outreach Automations" description="Frontend workflow states; no emails are scheduled or sent"><template #actions><ZButton @click="r.push('/outreach/compose')">New sequence</ZButton></template></PageHeader><Panel><DataTable :columns="columns" :rows="rows" :min-width="1100"><template #name="{row}"><button class="font-medium text-primary hover:underline" @click="r.push(`/outreach/automations/${row.id}`)">{{row.name}}</button></template><template #active="{row}"><span class="num">{{row.status==='Active'?row.enrolled-row.completed:0}}</span></template><template #openRate="{row}"><span class="num">{{row.openRate}}%</span></template><template #replyRate="{row}"><span class="num">{{row.replyRate}}%</span></template><template #status="{row}"><StatusBadge :status="row.status"/></template><template #actions="{row}"><div class="flex justify-end gap-1"><ZButton variant="ghost" @click="r.push(`/outreach/automations/${row.id}`)">View</ZButton><ZButton v-if="row.status==='Active'" variant="ghost" @click="local[row.id]='Paused'">Pause</ZButton><ZButton v-else variant="ghost" @click="local[row.id]='Active'">Activate</ZButton></div></template></DataTable></Panel></AppShell></template>
